window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f970091e618a2139"]={"versions": [{"id": "FIG-f970091e618a2139", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellenspezifikation im Kontext des AUTOSAR Classic BSW-Moduls Diagnostic Communication Manager (DCM). Es beschreibt die statische Kopplung des DCM an externe Datenlieferanten zur Bereitstellung des gesetzlichen Diagnose-Dienstes OBD Service $01 (Request Current Powertrain Diagnostic Data).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Dcm</code> («module»): Basiskomponente des Diagnostic Communication Manager als Aufrufer/Konsument.\n</li><li><code>PidServices_&lt;PID&gt;</code> («interface»): Generische Schnittstelle zur Abfrage der Daten einer spezifischen Parameter-ID (PID).\n</li><li>Operation <code>GetPIDValue</code>: Funktionsdeklaration <code>GetPIDValue(return :Std_ReturnType, DataValueBuffer :uint8*)</code>. Nimmt den Pufferzeiger <code>DataValueBuffer</code> entgegen und liefert den Status <code>Std_ReturnType</code> zurück.\n</li><li><code>«configurable»</code>: Stereotyp an der Realisierungs-/Abhängigkeitsbeziehung zwischen <code>Dcm</code> und <code>PidServices_&lt;PID&gt;</code>, der kennzeichnet, dass die Zuordnung der Funktionen pro PID zur Konfigurationszeit vorgenommen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Diagramm ohne Sequenzverlauf. Zur Laufzeit ruft das DCM bei einer Diagnoseanfrage für OBD Service $01 für die jeweils angeforderte PID synchron die konfigurierte Funktion <code>GetPIDValue</code> auf, welche die aktuellen Messwerte direkt in den bereitgestellten <code>DataValueBuffer</code> schreibt, damit das DCM die positive Response zusammensetzen kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Schnittstellensignatur für die Anbindung von Anwendungs-SWCs oder Sensor-Treibern an den DCM für OBD Service $01. Für jede im DCM konfigurierte PID muss eine entsprechende C-Funktion bzw. Port-Operation mit exakt dieser Signatur implementiert und bereitgestellt werden. Der Aufrufer (DCM) garantiert die Bereitstellung des Zielspeichers <code>DataValueBuffer</code>, welcher für die Nutzdatenlänge der jeweiligen PID dimensioniert sein muss.</p>"}, {"id": "FIG-3e58a4ec7b2a4805", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellenspezifikation im Kontext des AUTOSAR Classic BSW-Moduls Diagnostic Communication Manager (DCM). Es beschreibt die statische Kopplung des DCM an externe Datenlieferanten zur Bereitstellung des gesetzlichen Diagnose-Dienstes OBD Service $01 (Request Current Powertrain Diagnostic Data).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Dcm</code> («module»): Basiskomponente des Diagnostic Communication Manager als Aufrufer/Konsument.\n</li><li><code>PidServices_&lt;PID&gt;</code> («interface»): Generische Schnittstelle zur Abfrage der Daten einer spezifischen Parameter-ID (PID).\n</li><li>Operation <code>GetPIDValue</code>: Funktionsdeklaration <code>GetPIDValue(return :Std_ReturnType, DataValueBuffer :uint8*)</code>. Nimmt den Pufferzeiger <code>DataValueBuffer</code> entgegen und liefert den Status <code>Std_ReturnType</code> zurück.\n</li><li><code>«configurable»</code>: Stereotyp an der Realisierungs-/Abhängigkeitsbeziehung zwischen <code>Dcm</code> und <code>PidServices_&lt;PID&gt;</code>, der kennzeichnet, dass die Zuordnung der Funktionen pro PID zur Konfigurationszeit vorgenommen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Diagramm ohne Sequenzverlauf. Zur Laufzeit ruft das DCM bei einer Diagnoseanfrage für OBD Service $01 für die jeweils angeforderte PID synchron die konfigurierte Funktion <code>GetPIDValue</code> auf, welche die aktuellen Messwerte direkt in den bereitgestellten <code>DataValueBuffer</code> schreibt, damit das DCM die positive Response zusammensetzen kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Schnittstellensignatur für die Anbindung von Anwendungs-SWCs oder Sensor-Treibern an den DCM für OBD Service $01. Für jede im DCM konfigurierte PID muss eine entsprechende C-Funktion bzw. Port-Operation mit exakt dieser Signatur implementiert und bereitgestellt werden. Der Aufrufer (DCM) garantiert die Bereitstellung des Zielspeichers <code>DataValueBuffer</code>, welcher für die Nutzdatenlänge der jeweiligen PID dimensioniert sein muss.</p>"}], "trans": [{"from": "FIG-f970091e618a2139", "to": "FIG-3e58a4ec7b2a4805", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Äußerer Diagrammrahmen: Der UML-Rahmen mit dem Kopfbereich <code>class OBD Service $01</code> wurde entfernt.\n</li><li>Modulsymbol <code>Dcm</code>: Das Schnittstellen-/Konnektorsymbol (zwei verbundene Kreise) in der unteren rechten Ecke der Modul-Box wurde entfernt; das Komponenten-Icon oben rechts bleibt erhalten.\n</li><li>Typografie: Die Kursivierung des Schnittstellennamens <code>PidServices_&lt;PID&gt;</code> und der Operation <code>GetPIDValue(...)</code> wurde aufgehoben (nun in normalem Schriftschnitt).\n</li></ul>"}]};
